def apply_inventory_ui(destination: Path) -> None:
    """Verify all before/after bytes; apply only to a freshly extracted source tree."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest_bytes = manifest_file.read_bytes()
    manifest = json.loads(manifest_bytes)
    if manifest.get('format') != 'aj-release-files-1' or manifest.get('version') != '1.34.19':
        raise ValueError('Inventory UI03 requires the reviewed 1.34.19 source.')
    if (destination / 'UI_PATCH.json').exists():
        raise ValueError('An overlay is already present; start from the verified original parts.')
    prepared = {}
    for name, record in _UI_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New overlay resource unexpectedly exists: ' + name)
        elif manifest['files'].get(name) != expected or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Inventory UI03 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(base64.b64decode(record['zlib_base64'],validate=True),record['bytes']+1)
        if (not decompressor.eof or decompressor.unused_data or len(content)!=record['bytes']
                or hashlib.sha256(content).hexdigest()!=record['after_sha256']):
            raise ValueError('Inventory UI03 payload integrity failure: '+name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination/name
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI_FILES[name]['after_sha256']
    provenance = {
        'format':'wavelink-source-overlay-1',
        'patch_id':UI_PATCH_ID,
        'upstream_version':'1.34.19',
        'upstream_archive_sha256':SOURCE_SHA256,
        'upstream_release_manifest_sha256':hashlib.sha256(manifest_bytes).hexdigest(),
        'includes':['inventory-ui01-2026-09-24','inventory-ui02-2026-09-24'],
        'scope':'Cumulative inventory UI and explicit saved category metadata. Existing physical movement, custody and authentication logic unchanged.',
        'data_changes':'Only an authorised, confirmed category action adds classification JSON to an inventory list; no automatic seeding, SQL table migration or item-row rewrite.',
        'changed_files':{name:{key:val for key,val in record.items() if key!='zlib_base64'} for name,record in _UI_FILES.items()},
    }
    content=(json.dumps(provenance,indent=2)+'\n').encode()
    (destination/'UI_PATCH.json').write_bytes(content)
    manifest['variant']=UI_PATCH_ID
    manifest['files']['UI_PATCH.json']=hashlib.sha256(content).hexdigest()
    manifest_file.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived source integrity failure: '+name)

if __name__ == '__main__':
    incoming=Path(sys.argv[1])
    count=(extract_parts if incoming.name=='source_parts.json' else extract)(incoming,Path(sys.argv[2]))
    print(f'Verified upstream 1.34.19: {count} tracked files.')
    print('Applied Inventory UI 03: category tools and cumulative UI; demo data changes require explicit administrator review.')
